			color: rgba(255, 255, 255, 0.92) !important;
			margin-bottom: 12px !important;
		}
		.vwd-hero-title {
			color: #ffffff !important;
			font-weight: 700 !important;
			letter-spacing: -0.5px;
			margin-bottom: 0;
			white-space: nowrap;
		}
		.vwd-rotator-wrapper {
			display: inline-block;
			position: relative;
			vertical-align: baseline;
			transition: width 0.35s cubic-bezier(0.4, 0, 0.2, 1);
			text-align: left;
		}
		.vwd-rotator-text {
			display: inline-block;
			color: #CFB165;
			transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.2, 0.8, 0.2, 1);
			transform: translateY(0);
			opacity: 1;
			will-change: transform, opacity;
			white-space: nowrap;
		}
		@supports (-webkit-background-clip: text) or (background-clip: text) {
			.vwd-rotator-text {
				background: linear-gradient(135deg, #CFB165 0%, #F5DE98 50%, #CFB165 100%);
				-webkit-background-clip: text;
				-webkit-text-fill-color: transparent;
			}
		}
		.vwd-rotator-text.slide-out {
			opacity: 0;
			transform: translateY(-24px);
		}
		.vwd-rotator-text.slide-in-prep {
			opacity: 0;
			transform: translateY(24px);
			transition: none !important;
		}
		.vwd-rotator-text.slide-in {
			opacity: 1;
			transform: translateY(0);
		}
